<script setup>
import {ref,onMounted,onUnmounted,watch,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {session,ui,api,restore,notify} from './lib/api.js';import {dateLabel,initials} from './lib/format.js';import Login from './views/Login.vue';import Icon from './components/Icon.vue';import Modal from './components/Modal.vue';import Portal from './views/Portal.vue';import AccountSecurity from './components/AccountSecurity.vue';
const route=useRoute(),router=useRouter(),mobile=ref(false),searchOpen=ref(false),search=ref(''),results=ref([]),searchBusy=ref(false),notificationOpen=ref(false),notifications=ref([]);
const links=[['/','Vue d’ensemble','LayoutDashboard','01'],['/clients','Clients','Users','02'],['/quotes','Devis','FileText','03'],['/projects','Projets','FolderKanban','04'],['/invoices','Factures','Receipt','05'],['/expenses','Dépenses','Wallet','06'],['/services','Prestations','Layers','07'],['/documents','Documents','FolderOpen','08'],['/calendar','Calendrier','CalendarDays','09'],['/finances','Finances','ChartNoAxesCombined','10'],['/apporteurs','Apporteurs','Handshake','11']];
const current=computed(()=>route.path.startsWith('/equipe')?'Accès & rôles':links.find(l=>l[0]==='/'?route.path==='/':route.path.startsWith(l[0]))?.[1]||'Paramètres');const unread=computed(()=>notifications.value.filter(n=>!n.read).length);
let timer,request=0;
watch(search,value=>{clearTimeout(timer);const token=++request;results.value=[];if(value.trim().length<2)return;timer=setTimeout(async()=>{searchBusy.value=true;try{const r=await api('/search?q='+encodeURIComponent(value));if(token===request)results.value=r;}catch(e){notify(e.message,'error');}finally{if(token===request)searchBusy.value=false;}},200);});
watch(()=>route.fullPath,()=>{mobile.value=false;searchOpen.value=false;});
async function loadNotifications(){if(!session.user)return;try{notifications.value=await api('/notifications');}catch{}}
watch([()=>session.user,()=>ui.revision],loadNotifications);
function key(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(session.user)searchOpen.value=!searchOpen.value;}}
async function logout(){try{await api('/auth/logout',{method:'POST'});session.user=null;session.csrf='';router.push('/');}catch(e){notify(e.message,'error');}}
async function markRead(){try{await api('/notifications/read',{method:'POST',body:{keys:notifications.value.map(n=>n.key)}});await loadNotifications();}catch(e){notify(e.message,'error');}}
function followResult(r){searchOpen.value=false;notificationOpen.value=false;if(r.type==='documents')window.open(`/api/documents/${r.id}/download`,'_blank','noopener');else router.push(r.type==='subscriptions'?'/finances':`/${r.type}/${r.entityId||r.id}`);}
onMounted(async()=>{document.addEventListener('keydown',key);await restore();await loadNotifications();});onUnmounted(()=>{document.removeEventListener('keydown',key);clearTimeout(timer);});
</script>
<template><div v-if="!session.ready" class="boot"><span class="brand-mark">bw</span><span>OUVERTURE DU STUDIO…</span></div><RouterView v-else-if="route.meta.public"/><Login v-else-if="!session.user"/><Portal v-else-if="session.user.role==='referrer'"/><main v-else-if="!session.user.totpEnabled" class="public-page privacy-page"><span class="eyebrow">SÉCURITÉ / ÉTAPE OBLIGATOIRE</span><h1>DOUBLE AUTHENTIFICATION.</h1><p>Le compte administrateur donne accès aux données clients et comptables : activez la double authentification pour entrer dans le studio.</p><AccountSecurity only2fa/><button class="text-button" type="button" @click="logout">Se déconnecter</button></main><div v-else class="app-shell"><div v-if="mobile" class="sidebar-scrim" @click="mobile=false"></div><aside class="sidebar" :class="{expanded:mobile}"><RouterLink to="/" class="brand"><span class="brand-mark">b<span>w</span></span><span>birostweb<span class="accent">.</span></span></RouterLink><div class="workspace-label"><span class="live-dot"></span>ESPACE STUDIO <span>↗</span></div><span class="nav-label">PILOTER L’ACTIVITÉ</span><nav><RouterLink v-for="[path,label,icon,number] in links" :key="path" :to="path" :class="{active:path==='/'?route.path==='/':route.path.startsWith(path)}"><Icon :name="icon" :size="18"/><span>{{label}}</span><small>{{number}}</small></RouterLink></nav><div class="sidebar-bottom"><RouterLink class="settings-link" to="/equipe"><Icon name="Users"/>Accès &amp; rôles<Icon name="ArrowUpRight" :size="15"/></RouterLink><RouterLink class="settings-link" to="/settings"><Icon name="Settings"/>Paramètres<Icon name="ArrowUpRight" :size="15"/></RouterLink><nav class="legal-links" aria-label="Informations légales"><a href="https://birostweb.fr/mentions-legales.html" target="_blank" rel="noopener">Mentions légales</a><RouterLink to="/confidentialite">Confidentialité</RouterLink></nav><div class="sidebar-signature"><span>FAIT POUR<br><strong>CRÉER LA SUITE.</strong></span><span class="slash-mark">///</span></div><div class="user-block"><span class="avatar">{{initials(session.user.name)}}</span><div><strong>{{session.user.name}}</strong><small>Administrateur</small></div><button class="icon-button" aria-label="Se déconnecter" title="Se déconnecter" @click="logout"><Icon name="LogOut" :size="16"/></button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" aria-label="Ouvrir le menu" @click="mobile=true"><Icon name="Menu"/></button><span>STUDIO</span><span class="muted">/</span><strong>{{current}}</strong></div><div class="topbar-actions"><button class="search-trigger" @click="searchOpen=true"><Icon name="Search" :size="16"/><span>Rechercher…</span><kbd>⌘ K</kbd></button><button class="notification-trigger icon-button" aria-label="Ouvrir les notifications" @click="notificationOpen=true"><Icon name="Bell"/><i v-if="unread"></i></button><span class="topbar-divider"></span><span class="avatar small">{{initials(session.user.name)}}</span></div></header><main class="main-content"><RouterView :key="route.fullPath"/></main></div></div><Modal :open="searchOpen" title="RECHERCHER." @close="searchOpen=false"><label class="search-field"><Icon name="Search"/><input v-model="search" placeholder="Un client, un projet, une référence…" autofocus aria-label="Recherche globale"></label><div class="search-results"><p v-if="searchBusy" class="muted">Recherche en cours…</p><button v-for="r in results" :key="r.type+r.id" class="search-result" @click="followResult(r)"><div><strong>{{r.title}}</strong><small>{{r.type}} · {{r.detail}}</small></div><Icon name="ArrowUpRight"/></button><p v-if="search.length>=2&&!results.length&&!searchBusy" class="muted">Aucun résultat pour « {{search}} ».</p><p v-if="search.length<2" class="muted">Saisissez au moins deux caractères.</p></div></Modal><Modal :open="notificationOpen" title="À VOTRE ATTENTION." @close="notificationOpen=false"><div class="row-between"><span>{{unread}} notification{{unread>1?'s':''}} non lue{{unread>1?'s':''}}</span><button class="text-button" @click="markRead"><Icon name="CheckCheck"/>Tout marquer comme lu</button></div><button v-for="n in notifications" :key="n.key" class="search-result" :class="{muted:n.read}" @click="followResult(n)"><div><strong>{{n.title}}</strong><small>{{dateLabel(n.date)}} · {{n.detail}}</small></div><Icon name="ArrowUpRight"/></button><p v-if="!notifications.length" class="muted">Aucune échéance urgente. Tout est à jour.</p></Modal><div class="toasts" aria-live="polite"><div v-for="t in ui.toasts" :key="t.id" class="toast" :class="t.type"><Icon :name="t.type==='error'?'X':'Check'"/>{{t.message}}<button aria-label="Fermer le message" @click="ui.toasts=ui.toasts.filter(v=>v.id!==t.id)"><Icon name="X" :size="14"/></button></div></div></template>
